// Agent-operated native controls and router checks; no physical-keyboard or human-solving claim.
using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Windows.Forms;
internal static class FunctionsNativeChecks {
 static T Field<T>(ExperimentShell s,string name){return (T)typeof(ExperimentShell).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(s);}
 static Dictionary<string,object> Map(object x){return (Dictionary<string,object>)x;}
 static string Json(object x){return new JavaScriptSerializer().Serialize(x);}
 static Dictionary<string,object> Copy(object x){return Map(new JavaScriptSerializer().DeserializeObject(Json(x)));}
 static Dictionary<string,object> Section(Dictionary<string,object> x,string name){object value;if(!x.TryGetValue(name,out value)||value==null){value=new Dictionary<string,object>();x[name]=value;}return Map(value);}
 static ExperimentInputState State(ExperimentShell s){return (ExperimentInputState)typeof(ExperimentShell).GetMethod("InputState",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(s,null);}
 static bool Extras(ExperimentShell s){return (bool)typeof(ExperimentShell).GetProperty("KeyboardExtrasVisible",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(s,null);}
 static bool Exposed(Control c){if(!c.Visible||!c.IsHandleCreated)return false;Rectangle expected=c.RectangleToScreen(c.ClientRectangle),visible=expected;for(Control p=c.Parent;p!=null;p=p.Parent)visible=Rectangle.Intersect(visible,p.RectangleToScreen(p.ClientRectangle));return expected==visible;}
 internal static async Task Run(ExperimentShell shell,Form host,Func<Task> ready,Func<Dictionary<string,object>,Task<bool>> send,Action<bool,string> check,Action<string,Form> image){
  var input=Field<ExperimentInput>(shell,"input");var panel=Field<FlowLayoutPanel>(shell,"keyboard");var window=Field<Dictionary<string,Form>>(shell,"workWindows")["keyboard"];var original=Copy(Map(shell.Work["workspace"])["keybinds"]);string originalBank=Convert.ToString(Map(shell.Work["workspace"])["bank"]);Exception failure=null;
  try{
   check(await send(LocalApi.D("action","bank","id","33-A")),"Functions fixture selects a physical set explicitly");await ready();
   var bindings=Copy(original);Section(bindings,"commands").Remove("Backslash");Section(bindings,"twists").Remove("Backslash");var local=Section(Section(bindings,"banks"),"33-A");Section(local,"commands").Remove("Backslash");Section(local,"twists").Remove("Backslash");local.Remove("grips");bindings["grips"]=new[]{"Digit1"};
   check(await send(LocalApi.D("action","settings","keybinds",bindings)),"Functions fixture preserves unrelated custom bindings");await ready();
   string hash=Convert.ToString(shell.Work["hash"]),draft=Json(Map(shell.Work["workspace"])["draft"]),current=Json(shell.Work["current"]),next=Json(shell.Work["next"]);bool extras=Extras(shell);
   var state=State(shell);check(state.CommandKeys["Backslash"]=="functions-toggle","Default physical Backslash opens Functions");
   window.Activate();panel.Focus();input.Reset("Functions checks start with released input.");check(input.HandleKeyDown("Backslash",false,false,false,false,false),"Functions entry uses the real input router");input.HandleKeyUp("Backslash");await ready();
   check(Convert.ToString(Map(shell.Work["workspace"])["bank"])=="Functions"&&Convert.ToString(Map(shell.Work["workspace"])["previous_bank"])=="33-A","Functions records the exact previous bank");
   var rows=Field<List<TableLayoutPanel>>(shell,"additionalKeyboardRows").Where(r=>Object.Equals(r.Tag,"chords")).ToArray();check(rows.Length>0&&rows.All(r=>r.Visible)&&Extras(shell)==extras,"Functions displays combinations without changing the normal Extras preference");
   var keys=Field<Dictionary<Button,string>>(shell,"physicalKeyboardKeys");foreach(var key in keys.Where(p=>p.Value.Contains("+")).Select(p=>p.Key)){panel.ScrollControlIntoView(key);check(Exposed(key),"Functions combination is reachable: "+key.Text.Replace('\n',' '));}
   image("functions-combinations",window);panel.AutoScrollPosition=Point.Empty;
   check(await send(LocalApi.D("action","bank","id","Functions")),"Selecting current Functions is accepted as no-op");await ready();check(Convert.ToString(Map(shell.Work["workspace"])["previous_bank"])=="33-A","Repeated Functions selection keeps the return destination");
   window.Activate();panel.Focus();input.Reset("Functions return starts released.");input.HandleKeyDown("Backslash",false,false,false,false,false);input.HandleKeyUp("Backslash");await ready();
   check(Convert.ToString(Map(shell.Work["workspace"])["bank"])=="33-A"&&Extras(shell)==extras,"The same key returns directly to the previous set");
   input.Reset("Text owns this input.");input.HandleKeyDown("Backslash",false,false,false,false,true);input.HandleKeyUp("Backslash");check(Convert.ToString(Map(shell.Work["workspace"])["bank"])=="33-A"&&!input.Pending,"Typing Backslash does not switch sets");input.SetComposition(true);input.HandleKeyDown("Backslash",false,false,false,false,false);input.HandleKeyUp("Backslash");input.SetComposition(false);check(Convert.ToString(Map(shell.Work["workspace"])["bank"])=="33-A","IME Backslash does not switch sets");
   foreach(string kind in new[]{"grip","twist","command","null"}){var custom=Copy(bindings);if(kind=="grip")custom["grips"]=new[]{"Backslash"};if(kind=="twist")Section(custom,"twists")["Backslash"]="H1";if(kind=="command")Section(custom,"commands")["Backslash"]="review";if(kind=="null")Section(custom,"commands")["Backslash"]=null;check(await send(LocalApi.D("action","settings","keybinds",custom)),"Functions compatibility accepts "+kind);await ready();state=State(shell);check(kind=="command"?state.CommandKeys["Backslash"]=="review":!state.CommandKeys.ContainsKey("Backslash"),"Existing Backslash "+kind+" is not silently replaced");if(kind=="grip")check(state.GripKeys.ContainsKey("Backslash"),"Existing physical Grip remains mapped");if(kind=="twist")check(state.TwistKeys["Backslash"]=="H1","Existing exact Twist remains mapped");}
   var localNull=Copy(bindings);Section(localNull,"commands")["Backslash"]="functions-toggle";Section(Section(Section(localNull,"banks"),"33-A"),"commands")["Backslash"]=null;check(await send(LocalApi.D("action","settings","keybinds",localNull)),"Functions accepts explicit shared toggle plus local null override");await ready();check(!State(shell).CommandKeys.ContainsKey("Backslash"),"Local null wins over the shared Functions shortcut without silent replacement");
   check(Convert.ToString(shell.Work["hash"])==hash&&Json(Map(shell.Work["workspace"])["draft"])==draft&&Json(shell.Work["current"])==current&&Json(shell.Work["next"])==next,"Functions browsing and key editing preserve mechanics, draft, Current and Next");
  }catch(Exception error){failure=error;}finally{input.HandleKeyUp("Backslash");input.SetComposition(false);input.Reset("Functions check ended; release input.");}
  try{check(await send(LocalApi.D("action","settings","keybinds",original)),"Functions fixture restores original bindings");await ready();check(await send(LocalApi.D("action","bank","id",originalBank)),"Functions fixture restores original bank");await ready();}catch(Exception restore){if(failure!=null)throw new AggregateException(failure,restore);throw;}
  if(failure!=null)throw new InvalidOperationException("Functions native check: "+failure.Message,failure);
 }
}
